import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Directrices Éticas del Alma Dual","description":"","frontmatter":{},"headers":[],"relativePath":"es/58-双魂伦理准则.md","filePath":"es/58-双魂伦理准则.md","lastUpdated":null}'),n={name:"es/58-双魂伦理准则.md"};function d(r,e,s,t,c,m){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="directrices-eticas-del-alma-dual" tabindex="-1">Directrices Éticas del Alma Dual <a class="header-anchor" href="#directrices-eticas-del-alma-dual" aria-label="Permalink to &quot;Directrices Éticas del Alma Dual&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>58</td></tr><tr><td>Módulo</td><td>Razas y Formas de Vida</td></tr><tr><td>Palabras clave</td><td>Ética del alma dual, derechos de la personalidad, dignidad del alma, equilibrio de intereses, revisión ética</td></tr></tbody></table><h2 id="i-el-planteamiento-del-problema-etico-del-alma-dual" tabindex="-1">I. El Planteamiento del Problema Ético del Alma Dual <a class="header-anchor" href="#i-el-planteamiento-del-problema-etico-del-alma-dual" aria-label="Permalink to &quot;I. El Planteamiento del Problema Ético del Alma Dual&quot;">​</a></h2><p>El problema ético del alma dual es el problema ético fundamental que la Civilización Simbiótica del Ancla debe responder al enfrentarse a las Entidades Oscuras de Reemplazo (véase <em>57-黑暗置换体起源与本质</em>). Cuando un solo cuerpo contiene dos almas independientes — el alma anfitriona original y el alma de reemplazo oscura — surge una serie de profundos problemas éticos:</p><ul><li>¿Poseen ambas almas derechos de personalidad independientes?</li><li>¿Prevalecen los derechos del alma anfitriona original sobre los del alma de reemplazo oscura?</li><li>¿Es moral aniquilar el alma de reemplazo oscura para proteger el alma anfitriona original?</li><li>Cuando los intereses de las dos almas entran en conflicto, ¿cómo deben ponderarse?</li><li>¿Tiene la sociedad la obligación de invertir recursos en rescatar almas anfitrionas originales que han sido oscuramente reemplazadas?</li><li>¿Tiene el alma de reemplazo oscura un &quot;derecho a existir&quot;?</li></ul><p>Estos problemas no tienen respuestas simples; deben establecerse principios éticos sistemáticos para guiar la práctica. Las Directrices Éticas del Alma Dual son precisamente el documento normativo formulado en respuesta a estos problemas, y constituyen el fundamento ético para la identificación, el tratamiento y el manejo de las Entidades Oscuras de Reemplazo.</p><h2 id="ii-principios-basicos-de-la-etica-del-alma-dual" tabindex="-1">II. Principios Básicos de la Ética del Alma Dual <a class="header-anchor" href="#ii-principios-basicos-de-la-etica-del-alma-dual" aria-label="Permalink to &quot;II. Principios Básicos de la Ética del Alma Dual&quot;">​</a></h2><p>Las Directrices Éticas del Alma Dual establecen los siguientes seis principios básicos como piedra angular de valor para manejar los problemas del alma dual:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Connotación</th></tr></thead><tbody><tr><td>Principio de dignidad del alma</td><td>Toda alma con conciencia independiente goza de una dignidad inherente y no debe ser arbitrariamente aniquilada o esclavizada</td></tr><tr><td>Principio de prioridad del alma original</td><td>En los conflictos del alma dual, los derechos legítimos del alma anfitriona original prevalecen sobre los del alma de reemplazo oscura, porque el anfitrión original es el propietario legítimo del cuerpo</td></tr><tr><td>Principio de menor daño</td><td>Al manejar problemas del alma dual, debe elegirse la opción que cause el menor daño a todas las partes relevantes, evitando en la medida de lo posible la aniquilación de almas</td></tr><tr><td>Principio de proporcionalidad</td><td>Las medidas tomadas deben corresponder al grado de riesgo de la entidad del alma dual; el manejo excesivo está prohibido</td></tr><tr><td>Principio de consentimiento informado</td><td>Cuando el alma anfitriona original puede expresar su voluntad, las decisiones importantes que involucran el cuerpo y el alma del anfitrión original deben obtener su consentimiento</td></tr><tr><td>Principio de rescate con el mejor esfuerzo</td><td>La sociedad tiene la obligación de hacer todo esfuerzo razonable para rescatar a las almas anfitrionas originales que han sido oscuramente reemplazadas, y no debe rendirse fácilmente</td></tr></tbody></table><h2 id="iii-determinacion-de-los-derechos-de-personalidad-de-las-dos-almas" tabindex="-1">III. Determinación de los Derechos de Personalidad de las Dos Almas <a class="header-anchor" href="#iii-determinacion-de-los-derechos-de-personalidad-de-las-dos-almas" aria-label="Permalink to &quot;III. Determinación de los Derechos de Personalidad de las Dos Almas&quot;">​</a></h2><p>El problema primordial de la ética del alma dual es la determinación de los derechos de personalidad de las dos almas. Estas Directrices establecen las siguientes reglas de determinación:</p><h3 id="i-derechos-de-personalidad-del-alma-anfitriona-original" tabindex="-1">(I) Derechos de Personalidad del Alma Anfitriona Original <a class="header-anchor" href="#i-derechos-de-personalidad-del-alma-anfitriona-original" aria-label="Permalink to &quot;(I) Derechos de Personalidad del Alma Anfitriona Original&quot;">​</a></h3><p>El alma anfitriona original es la propietaria legítima del cuerpo, y sus derechos de personalidad son plenamente reconocidos y protegidos:</p><ol><li>El alma anfitriona original goza de todos los derechos básicos conferidos por la Constitución Simbiótica, incluidos el derecho a la vida, el derecho a la integridad corporal, el derecho a la salud, el derecho a la dignidad personal, etc.</li><li>El alma anfitriona original tiene el poder de decisión final sobre su propio cuerpo; cuando puede expresar su voluntad, cualquier disposición importante que involucre el cuerpo debe obtener el consentimiento del anfitrión original.</li><li>Los derechos e intereses legítimos del alma anfitriona original, como los derechos de propiedad, los derechos de identidad y las relaciones sociales, están protegidos por la ley y no se pierden debido al reemplazo oscuro.</li><li>El alma anfitriona original tiene derecho a recibir rescate y apoyo sociales, incluidos el tratamiento de purificación, la asistencia legal, el asesoramiento psicológico, etc.</li><li>Incluso si está profundamente suprimida, los derechos de personalidad del alma anfitriona original persisten; no puede ser declarada muerta ni privada de derechos.</li></ol><h3 id="ii-derechos-de-personalidad-del-alma-de-reemplazo-oscura" tabindex="-1">(II) Derechos de Personalidad del Alma de Reemplazo Oscura <a class="header-anchor" href="#ii-derechos-de-personalidad-del-alma-de-reemplazo-oscura" aria-label="Permalink to &quot;(II) Derechos de Personalidad del Alma de Reemplazo Oscura&quot;">​</a></h3><p>La determinación de los derechos de personalidad del alma de reemplazo oscura es relativamente compleja; estas Directrices adoptan la posición de &quot;reconocimiento limitado&quot;:</p><table tabindex="0"><thead><tr><th>Etapa de desarrollo</th><th>Determinación de derechos de personalidad</th><th>Alcance de derechos</th></tr></thead><tbody><tr><td>Período de erosión energética (Primera etapa)</td><td>Sin personalidad independiente</td><td>Un alma independiente aún no se ha formado; sin derechos de personalidad independientes</td></tr><tr><td>Período de contaminación del alma (Segunda etapa)</td><td>Sin personalidad independiente</td><td>Todavía es un estado contaminado del alma anfitriona original; sin derechos de personalidad independientes</td></tr><tr><td>Período de formación de dos almas (Tercera etapa)</td><td>Derechos de personalidad limitados</td><td>Tiene conciencia independiente preliminar, goza de derechos básicos de dignidad del alma, pero no goza de derechos de control del cuerpo ni de ciudadanía plena</td></tr><tr><td>Período de dominación oscura (Cuarta etapa)</td><td>Derechos de personalidad limitados</td><td>Tiene conciencia completamente independiente, goza de derechos de dignidad del alma y del derecho a ser tratada con respeto, pero debido a su peligro, sus derechos están sujetos a restricciones necesarias</td></tr><tr><td>Período de reemplazo completo (Quinta etapa)</td><td>Derechos de personalidad plenos (pero como existencia hostil)</td><td>El anfitrión original ha perecido, el alma oscura se convierte en la única alma del cuerpo, con derechos de personalidad plenos, pero debido a su comportamiento hostil, pueden tomarse medidas coercitivas incluida la aniquilación conforme a la ley</td></tr></tbody></table><h3 id="iii-contenido-especifico-de-los-derechos-de-personalidad-limitados" tabindex="-1">(III) Contenido Específico de los Derechos de Personalidad Limitados <a class="header-anchor" href="#iii-contenido-especifico-de-los-derechos-de-personalidad-limitados" aria-label="Permalink to &quot;(III) Contenido Específico de los Derechos de Personalidad Limitados&quot;">​</a></h3><p>Los derechos de personalidad limitados que disfruta el alma de reemplazo oscura en las etapas tercera y cuarta incluyen:</p><ol><li><strong>Derecho a la dignidad del alma</strong>: no debe ser tratada con insulto, abuso o tortura; debe mantenerse el respeto básico incluso en el control y el manejo.</li><li><strong>Derecho a la aniquilación sin dolor</strong>: si finalmente se decide aniquilar el alma de reemplazo oscura, debe adoptarse un método sin dolor y rápido para reducir su sufrimiento.</li><li><strong>Derecho de expresión</strong>: en condiciones seguras y controlables, el alma de reemplazo oscura tiene derecho a expresar su voluntad y posición, pero su expresión no tiene fuerza jurídica vinculante.</li><li><strong>Derecho a ser escuchada</strong>: al tomar decisiones importantes que involucran el alma de reemplazo oscura, su opinión debe escucharse dentro de un alcance razonable.</li></ol><p>El alma de reemplazo oscura no goza de los siguientes derechos: derechos de control del cuerpo, libertad de movimiento, derechos políticos de ciudadanía, propiedad (los bienes del anfitrión original pertenecen al anfitrión original) y derechos reproductivos (para prevenir la propagación de linajes oscuros).</p><h2 id="iv-reglas-de-ponderacion-de-los-conflictos-de-intereses-del-alma-dual" tabindex="-1">IV. Reglas de Ponderación de los Conflictos de Intereses del Alma Dual <a class="header-anchor" href="#iv-reglas-de-ponderacion-de-los-conflictos-de-intereses-del-alma-dual" aria-label="Permalink to &quot;IV. Reglas de Ponderación de los Conflictos de Intereses del Alma Dual&quot;">​</a></h2><p>Cuando los intereses del alma anfitriona original y del alma de reemplazo oscura entran en conflicto, se ponderan según las siguientes reglas:</p><h3 id="i-tipos-de-conflicto-y-reglas-de-ponderacion" tabindex="-1">(I) Tipos de Conflicto y Reglas de Ponderación <a class="header-anchor" href="#i-tipos-de-conflicto-y-reglas-de-ponderacion" aria-label="Permalink to &quot;(I) Tipos de Conflicto y Reglas de Ponderación&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de conflicto</th><th>Regla de ponderación</th></tr></thead><tbody><tr><td>Conflicto de derechos de supervivencia (la supervivencia de una parte está condicionada a la desaparición de la otra)</td><td>El derecho de supervivencia del alma anfitriona original prevalece; cuando la coexistencia es imposible, primero se protege la supervivencia del anfitrión original</td></tr><tr><td>Conflicto de derechos de control del cuerpo</td><td>El alma anfitriona original tiene el derecho de control final sobre el cuerpo; el derecho de control del cuerpo del alma oscura está estrictamente restringido</td></tr><tr><td>Conflicto de derechos de expresión</td><td>La expresión del alma anfitriona original tiene fuerza jurídica vinculante; la expresión del alma oscura sirve solo como referencia</td></tr><tr><td>Conflicto de derechos de propiedad</td><td>El cuerpo y los bienes pertenecen al anfitrión original; el alma oscura no tiene derechos de propiedad</td></tr><tr><td>Conflicto de derechos de elección de tratamiento</td><td>El alma anfitriona original tiene derecho a elegir si acepta el tratamiento de purificación; el alma oscura no tiene derecho a impedirlo</td></tr><tr><td>Conflicto de método de manejo</td><td>Para los manejos que implican la aniquilación del alma oscura, la voluntad del alma anfitriona original tiene un papel decisivo (pero debe someterse a revisión ética)</td></tr></tbody></table><h3 id="ii-respeto-y-limitacion-de-la-voluntad-del-anfitrion-original" tabindex="-1">(II) Respeto y Limitación de la Voluntad del Anfitrión Original <a class="header-anchor" href="#ii-respeto-y-limitacion-de-la-voluntad-del-anfitrion-original" aria-label="Permalink to &quot;(II) Respeto y Limitación de la Voluntad del Anfitrión Original&quot;">​</a></h3><p>Cuando el alma anfitriona original puede expresar su voluntad, la voluntad del anfitrión original debe respetarse plenamente, con las siguientes excepciones:</p><ol><li>Las voluntades del anfitrión original que claramente dañan la seguridad pública o los derechos e intereses legítimos de otros no están protegidas.</li><li>Las expresiones de voluntad hechas por el anfitrión original bajo la influencia del alma oscura que no son auténticas no tienen validez jurídica.</li><li>Si el anfitrión original elige voluntariamente fusionarse con el alma oscura, debe realizarse una revisión ética estricta y una evaluación de riesgos para confirmar que la existencia tras la fusión no representará una amenaza para la sociedad.</li><li>Si el anfitrión original elige voluntariamente renunciar al tratamiento y aceptar el reemplazo completo por el alma oscura, la sociedad debe intervenir y aconsejar, pero si el anfitrión original está plenamente lúcido y lo confirma repetidamente, debe respetarse en última instancia su derecho de decisión autónoma (esta es una zona gris ética que requiere revisión caso por caso).</li></ol><h2 id="v-mecanismo-de-revision-etica-del-alma-dual" tabindex="-1">V. Mecanismo de Revisión Ética del Alma Dual <a class="header-anchor" href="#v-mecanismo-de-revision-etica-del-alma-dual" aria-label="Permalink to &quot;V. Mecanismo de Revisión Ética del Alma Dual&quot;">​</a></h2><p>Para garantizar que el manejo de los problemas del alma dual cumpla con los principios éticos, el Estado establece un mecanismo de revisión ética del alma dual:</p><h3 id="i-comite-de-revision-etica" tabindex="-1">(I) Comité de Revisión Ética <a class="header-anchor" href="#i-comite-de-revision-etica" aria-label="Permalink to &quot;(I) Comité de Revisión Ética&quot;">​</a></h3><ul><li><strong>Composición</strong>: compuesto por eticistas, juristas, científicos de la vida, cultivadores, representantes de razas alienígenas y representantes del público general; los expertos con experiencia en investigación o tratamiento de Entidades Oscuras de Reemplazo no deben ser menos de un tercio.</li><li><strong>Funciones</strong>: revisar y adjudicar los problemas éticos importantes que involucran almas duales, incluidas las decisiones de aniquilar almas oscuras, la aprobación de la fusión de almas duales y la determinación de la validez de la voluntad del anfitrión original.</li><li><strong>Independencia</strong>: el Comité de Revisión Ética ejerce sus funciones de forma independiente, sin interferencia de órganos administrativos ni individuos.</li><li><strong>Procedimiento</strong>: la revisión adopta un sistema de audiencias, tomando decisiones tras escuchar las opiniones del anfitrión original (si puede expresarse), del equipo de tratamiento, de los familiares, de los representantes sociales y de todas las partes.</li></ul><h3 id="ii-asuntos-que-deben-someterse-a-revision-etica" tabindex="-1">(II) Asuntos que Deben Someterse a Revisión Ética <a class="header-anchor" href="#ii-asuntos-que-deben-someterse-a-revision-etica" aria-label="Permalink to &quot;(II) Asuntos que Deben Someterse a Revisión Ética&quot;">​</a></h3><p>Los siguientes asuntos deben ser revisados y aprobados por el Comité de Revisión Ética del Alma Dual antes de su implementación:</p><ol><li>Implementar un manejo que aniquile el alma oscura para Entidades Oscuras de Reemplazo en las etapas tercera y cuarta.</li><li>Implementar una cirugía de fusión de almas duales en Entidades Oscuras de Reemplazo.</li><li>Implementar una cirugía de separación de almas en Entidades Oscuras de Reemplazo.</li><li>Tomar decisiones finales de manejo para Entidades Oscuras de Reemplazo cuya voluntad del anfitrión original sea renunciar al tratamiento.</li><li>Implementar planes de tratamiento que puedan causar daño al alma anfitriona original.</li><li>Realizar investigaciones científicas que involucren el alma en Entidades Oscuras de Reemplazo.</li><li>Otros asuntos que involucren problemas éticos importantes del alma dual.</li></ol><h2 id="vi-derechos-y-obligaciones-sociales-de-las-entidades-del-alma-dual" tabindex="-1">VI. Derechos y Obligaciones Sociales de las Entidades del Alma Dual <a class="header-anchor" href="#vi-derechos-y-obligaciones-sociales-de-las-entidades-del-alma-dual" aria-label="Permalink to &quot;VI. Derechos y Obligaciones Sociales de las Entidades del Alma Dual&quot;">​</a></h2><h3 id="i-derechos-sociales" tabindex="-1">(I) Derechos Sociales <a class="header-anchor" href="#i-derechos-sociales" aria-label="Permalink to &quot;(I) Derechos Sociales&quot;">​</a></h3><p>Mientras el alma anfitriona original aún exista, la entidad del alma dual (Entidad Oscura de Reemplazo) goza de los siguientes derechos sociales:</p><ol><li>El derecho a recibir seguridad básica de subsistencia y atención médica.</li><li>El derecho a recibir asistencia legal y consulta ética.</li><li>El derecho a contactar a familiares y amigos en condiciones seguras y controlables.</li><li>El derecho a recibir educación y participar en actividades culturales (dentro de instalaciones de aislamiento).</li><li>El derecho a apelar y solicitar revisión de las decisiones de manejo.</li></ol><h3 id="ii-obligaciones-y-restricciones-sociales" tabindex="-1">(II) Obligaciones y Restricciones Sociales <a class="header-anchor" href="#ii-obligaciones-y-restricciones-sociales" aria-label="Permalink to &quot;(II) Obligaciones y Restricciones Sociales&quot;">​</a></h3><p>La entidad del alma dual soporta simultáneamente las siguientes obligaciones y restricciones:</p><ol><li>La obligación de aceptar el control de aislamiento y el tratamiento.</li><li>La obligación de no atacar ni infectar a otras formas de vida (los infractores estarán sujetos a un control más estricto).</li><li>La obligación de cooperar con la evaluación de identificación y el monitoreo.</li><li>La libertad de movimiento está estrictamente restringida; no debe abandonar la instalación de aislamiento antes de ser curada.</li><li>No debe dedicarse al cultivo, la propagación de energía oscura u otras actividades que puedan agravar el reemplazo.</li></ol><h2 id="vii-controversias-de-frontera-en-la-etica-del-alma-dual" tabindex="-1">VII. Controversias de Frontera en la Ética del Alma Dual <a class="header-anchor" href="#vii-controversias-de-frontera-en-la-etica-del-alma-dual" aria-label="Permalink to &quot;VII. Controversias de Frontera en la Ética del Alma Dual&quot;">​</a></h2><p>Quedan algunas controversias de frontera en el campo de la ética del alma dual que aún no han alcanzado consenso y requieren exploración continua en la práctica:</p><ol><li><strong>El problema del &quot;pecado original&quot; del alma oscura</strong>: el alma de reemplazo oscura es destructiva desde su nacimiento. ¿Significa esto que es inherentemente &quot;mala&quot;? ¿Es posible un alma oscura &quot;bondadosa&quot;?</li><li><strong>La legitimidad ética de la fusión de almas</strong>: la nueva alma producida por la fusión de almas duales no es ni el anfitrión original ni el alma oscura. ¿Cómo se determina el estatus ético de esta &quot;tercera existencia&quot;?</li><li><strong>El límite de la inversión de recursos</strong>: ¿cuántos recursos debe invertir la sociedad para rescatar el alma anfitriona original dentro de una Entidad Oscura de Reemplazo? Cuando el costo del rescate es extremadamente alto y la tasa de éxito extremadamente baja, ¿sigue existiendo la obligación de hacer el mejor esfuerzo?</li><li><strong>La posibilidad de reformar el alma oscura</strong>: ¿puede el alma oscura reformarse en una existencia no destructiva mediante la educación, la reforma, la transformación energética y otros medios? Si es así, ¿debe el alma oscura reformada obtener derechos de personalidad plenos?</li><li><strong>El equilibrio entre prevención y privacidad</strong>: para prevenir la generación de Entidades Oscuras de Reemplazo, ¿es permisible monitorear a los seres vivos para detectar exposición a la Energía Abisal? ¿Viola dicho monitoreo la privacidad del alma?</li></ol><p>Estas controversias son estudiadas continuamente por las instituciones de investigación de ética del alma dual; el Comité de Revisión Ética toma decisiones en casos individuales según las circunstancias específicas, y las conclusiones relevantes actualizarán continuamente estas Directrices.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Las Directrices Éticas del Alma Dual son una manifestación profunda de la ética de la vida de la Civilización Simbiótica del Ancla. Al establecer principios básicos como la dignidad del alma, la prioridad del alma original y el menor daño, determinar los límites de los derechos de personalidad de las dos almas y establecer reglas de ponderación de conflictos de intereses y mecanismos de revisión ética, proporcionan un fundamento ético sólido para la gobernanza de las Entidades Oscuras de Reemplazo. El espíritu central de la ética del alma dual es: incluso frente al enemigo más peligroso, no abandonar la defensa firme de la dignidad de la vida; incluso bajo la amenaza de seguridad más urgente, no cruzar la línea de base ética. Esta es precisamente la marca fundamental que distingue la civilización simbiótica de la civilización depredadora.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (Origen y Esencia de las Entidades Oscuras de Reemplazo)</li><li>59-黑暗置换体四类分支处置 (Manejo de las Cuatro Ramas de las Entidades Oscuras de Reemplazo)</li><li>48-司法体系与裁决机制 (Sistema Judicial y Mecanismo de Adjudicación)</li><li>40-共生宪法总纲 (Sumario General de la Constitución Simbiótica)</li></ul>',50)])])}const h=a(n,[["render",d]]);export{p as __pageData,h as default};
